&lt;li style=&quot;font-size: 10pt; color: rgb(0, 0, 0); font-family: verdana, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 10pt; color: rgb(0, 0, 0); font-family: verdana, geneva, sans-serif;&quot;&gt;Quickly adapt and respond to industry changes as well as internal initiatives.&lt;/span&gt;&lt;/li&gt;
