&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt; font-family: verdana, geneva, sans-serif; color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: verdana, geneva, sans-serif; color: rgb(0, 0, 0);&quot;&gt;Must have a BA/BS and 15 years related experience, or MA/MS and 10 years related experience.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: verdana, geneva, sans-serif; color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: verdana, geneva, sans-serif; color: rgb(0, 0, 0);&quot;&gt;Relationship with TxDOT, and/or local agencies.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: verdana, geneva, sans-serif; color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: verdana, geneva, sans-serif; color: rgb(0, 0, 0);&quot;&gt;Current professional registration, if applicable.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: verdana, geneva, sans-serif; color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: verdana, geneva, sans-serif; color: rgb(0, 0, 0);&quot;&gt;Directly responsible for an individual sales goal.&lt;/span&gt;&lt;/li&gt;
