&lt;li style=&quot;font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;Manages through subordinate managers and professionals in larger groups of moderate complexity.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;Provides input to strategic decisions that affect the functional area of responsibility.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;Produce daily and weekly reports&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
