&lt;li style=&quot;font-family: verdana, geneva, sans-serif; color: rgb(0, 0, 0); font-weight: bold; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;Extended workdays: Employees should expect to work approximately 12–14 hours per day while traveling and working onsite.&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
