&lt;li style=&quot;font-family: verdana, geneva, sans-serif; color: rgb(0, 0, 0); font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif; color: rgb(0, 0, 0); font-size: 10pt;&quot;&gt;Bachelor’s Degree in Civil Engineering from an ABET-accredited program.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: verdana, geneva, sans-serif; color: rgb(0, 0, 0); font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif; color: rgb(0, 0, 0); font-size: 10pt;&quot;&gt;Active PE License in Ohio and Texas.&lt;/span&gt;&lt;/li&gt;
