&lt;ul&gt;
&lt;li style=&quot;color: rgb(0, 0, 0); font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;Develop fire suppression system layouts&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(0, 0, 0); font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;Perform hydraulic calculations&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(0, 0, 0); font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;Develop fire alarm system drawings&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(0, 0, 0); font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;Prepare construction documents&lt;/span&gt;&lt;/li&gt;
