&lt;li style=&quot;color: rgb(0, 0, 0); font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;Experience with fire alarm, mass notification, fire suppression, fire pump, hydraulic calculation, special suppression, smoke control/exhaust, and fire-resistance rated construction.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(0, 0, 0); font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;Experience with smoke control rational analysis, CONTAM or CFD modeling, or other modeling software.&lt;/span&gt;&lt;/li&gt;
