&lt;li style=&quot;color: rgb(0, 0, 0); font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;Willing to travel to project sites or offices, as needed.&lt;/span&gt;&lt;/li&gt;
