&lt;li style=&quot;font-size: 10pt; font-family: verdana, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: verdana, geneva, sans-serif;&quot;&gt;Multibeam and&amp;nbsp;singlebeam&amp;nbsp;data processing&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
