&lt;li style=&quot;font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;Paid sick time, retirement plan, fitness reimbursement, pet insurance, identity protection, technology stipend, employee assistance program, and more!&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;Base pay offered may vary depending on job-related knowledge, skills, and experience.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Pay Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$87,100&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$108,900 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;Find out more about what Woolpert has to offer here:&amp;nbsp; &lt;a href=&quot;http://woolpert.com/about-us/&quot;&gt;http://woolpert.com/about-us/&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;
