&lt;ul&gt;
&lt;li style=&quot;color: rgb(0, 0, 0); font-size: 10pt; font-family: verdana, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 10pt; font-family: verdana, geneva, sans-serif;&quot;&gt;BS in Civil Engineering or related technical design field.&lt;/span&gt;&lt;/li&gt;
