&lt;li style=&quot;color: rgb(0, 0, 0); font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif; font-size: 10pt; color: rgb(0, 0, 0);&quot;&gt;Must have a Professional Surveyor License.&lt;/span&gt;&lt;/li&gt;
